/* From Uiverse.io by fanishah - Tags: icon, button */
.__UIV_SCOPE__ .button {
  font-family: inherit;
  background: #2CA0D9;
  color: white;
  padding: 0.35em 0;
  font-size: 17px;
  border: none;
  border-radius: 0.7em;
  letter-spacing: 0.08em;
  position: relative;
  display: flex;
  align-content: center;
  align-items: center;
  overflow: hidden;
  height: 2.5em;
  padding-left: 2.8em;
  padding-right: 0.92em;
}

.__UIV_SCOPE__ .button .icon {
  background: #fff;
  height: 2em;
  width: 2em;
  border-radius: 2em;
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  left: 0.4em;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .icon svg {
  margin-left: 0.1em;
  transition: all 0.5s;
  color: #2CA0D9;
  width: 1.2rem;
  height: 1.2rem;
}

.__UIV_SCOPE__ .button:hover .icon svg {
  transform: rotate(360deg);
}

.__UIV_SCOPE__ .button:hover .icon {
  width: calc(100% - 0.85rem);
  border-radius: 0.5em;
}
